 1 | // SPDX-License-Identifier: AGPL-3.0-only
 2 | pragma solidity 0.8.15;
 3 | 
 4 | import {ERC20} from "solmate/tokens/ERC20.sol";
 5 | import {ReentrancyGuard} from "solmate/utils/ReentrancyGuard.sol";
 6 | 
 7 | import {TransferHelper} from "libraries/TransferHelper.sol";
 8 | 
 9 | import "src/Kernel.sol";
10 | 
11 | // ERRORS
12 | error TRSRY_NotApproved();
13 | error TRSRY_NoDebtOutstanding();
14 | 
15 | /// @notice Treasury holds reserves, LP tokens and all other assets under the control
16 | ///         of the protocol.
17 | contract OlympusTreasury is Module, ReentrancyGuard {
18 |     using TransferHelper for ERC20;
19 | 
20 |     event ApprovedForWithdrawal(address indexed policy_, ERC20 indexed token_, uint256 amount_);
21 |     event Withdrawal(
22 |         address indexed policy_,
23 |         address indexed withdrawer_,
24 |         ERC20 indexed token_,
25 |         uint256 amount_
26 |     );
27 |     event DebtIncurred(ERC20 indexed token_, address indexed policy_, uint256 amount_);
28 |     event DebtRepaid(ERC20 indexed token_, address indexed policy_, uint256 amount_);
29 |     event DebtSet(ERC20 indexed token_, address indexed policy_, uint256 amount_);
30 | 
31 |     /// @notice Mapping of who is approved for withdrawal.
32 |     /// @dev    withdrawer -> token -> amount. Infinite approval is max(uint256).
33 |     mapping(address => mapping(ERC20 => uint256)) public withdrawApproval;
34 | 
35 |     /// @notice Total debt for token across all withdrawals.
36 |     mapping(ERC20 => uint256) public totalDebt;
37 | 
38 |     /// @notice Debt for particular token and debtor address
39 |     mapping(ERC20 => mapping(address => uint256)) public reserveDebt;
40 | 
41 |     /*//////////////////////////////////////////////////////////////
42 |                             MODULE INTERFACE
43 |     //////////////////////////////////////////////////////////////*/
44 | 
45 |     constructor(Kernel kernel_) Module(kernel_) {}
46 | 
47 |     function KEYCODE() public pure override returns (Keycode) {
48 |         return toKeycode("TRSRY");
49 |     }
50 | 
51 |     function VERSION() external pure override returns (uint8 major, uint8 minor) {
52 |         return (1, 0);
53 |     }
54 | 
55 |     /*//////////////////////////////////////////////////////////////
56 |                                CORE LOGIC
57 |     //////////////////////////////////////////////////////////////*/
58 | 
59 |     function getReserveBalance(ERC20 token_) external view returns (uint256) {
60 |         return token_.balanceOf(address(this)) + totalDebt[token_];

31 |         TRSRY = OlympusTreasury(getModuleAddress(dependencies[0]));
32 |     }
33 | 
34 |     function requestPermissions() external view override returns (Permissions[] memory requests) {
35 |         Keycode TRSRY_KEYCODE = TRSRY.KEYCODE();
36 | 
37 |         requests = new Permissions[](2);
38 |         requests[0] = Permissions(TRSRY_KEYCODE, TRSRY.setApprovalFor.selector);
39 |         requests[1] = Permissions(TRSRY_KEYCODE, TRSRY.setDebt.selector);
40 |     }
41 | 
42 |     function grantApproval(
43 |         address for_,
44 |         ERC20 token_,
45 |         uint256 amount_
46 |     ) external onlyRole("custodian") {
47 |         TRSRY.setApprovalFor(for_, token_, amount_);
48 |     }
49 | 
50 |     // Anyone can call to revoke a deactivated policy's approvals.
51 |     // TODO Currently allows anyone to revoke any approval EXCEPT activated policies.
52 |     // TODO must reorg policy storage to be able to check for deactivated policies.
53 |     function revokePolicyApprovals(address policy_, ERC20[] memory tokens_) external {
54 |         if (Policy(policy_).isActive()) revert PolicyStillActive();
55 | 
56 |         // TODO Make sure `policy_` is an actual policy and not a random address.
57 | 
58 |         uint256 len = tokens_.length;
59 |         for (uint256 j; j < len; ) {
60 |             TRSRY.setApprovalFor(policy_, tokens_[j], 0);
61 |             unchecked {
62 |                 ++j;
63 |             }
64 |         }
65 | 
66 |         emit ApprovalRevoked(policy_, tokens_);
67 |     }
68 | 
69 |     // Debt admin functions for authorized addresses to manipulate debt in special cases
70 | 
71 |     function increaseDebt(
72 |         ERC20 token_,
73 |         address debtor_,
74 |         uint256 amount_
75 |     ) external onlyRole("custodian") {
76 |         uint256 debt = TRSRY.reserveDebt(token_, debtor_);
77 |         TRSRY.setDebt(token_, debtor_, debt + amount_);
78 |     }
79 | 
80 |     function decreaseDebt(
81 |         ERC20 token_,
82 |         address debtor_,
83 |         uint256 amount_
84 |     ) external onlyRole("custodian") {
85 |         uint256 debt = TRSRY.reserveDebt(token_, debtor_);
86 |         TRSRY.setDebt(token_, debtor_, debt - amount_);
87 |     }
88 | }
